//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_number` previous retries.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        self.base_delay_ms
            .checked_mul(2u64.saturating_pow(retry_number))
            .unwrap_or(u64::MAX)
            .min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_growth_saturates_at_the_configured_maximum() {
        let config = RetryConfig {
            max_attempts: 5,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };

        assert_eq!(config.delay_for_retry(0), 10);
        assert_eq!(config.delay_for_retry(1), 20);
        assert_eq!(config.delay_for_retry(2), 25);
        assert_eq!(config.delay_for_retry(3), 25);
    }

    #[test]
    fn delay_calculation_is_safe_for_large_values() {
        let config = RetryConfig {
            max_attempts: 3,
            base_delay_ms: u64::MAX,
            max_delay_ms: u64::MAX,
        };

        assert_eq!(config.delay_for_retry(1), u64::MAX);
    }
}

